    // bars visibly show the clamp (P2-length output under the premium label).
    MODEL_TYPE_THINKING: { seen: 1, era: 'live' },
    MODEL_TYPE_EXPRESSIVE: { era: 'live' },
    MODEL_TYPE_FRENCH: { seen: 1, era: 'live' },
